import{_ as t,o as r,c as o,j as e,a as s}from"./chunks/framework.Ddwm6YJC.js";const f=JSON.parse('{"title":"第三卷 潮汐 · 第45章 长信一","description":"","frontmatter":{},"headers":[],"relativePath":"第45章_长信一.md","filePath":"第45章_长信一.md"}'),n={name:"第45章_长信一.md"};function _(c,a,d,l,i,p){return r(),o("div",null,[...a[0]||(a[0]=[e("h1",{id:"第三卷-潮汐-·-第45章-长信一",tabindex:"-1"},[s("第三卷 潮汐 · 第45章 长信一 "),e("a",{class:"header-anchor",href:"#第三卷-潮汐-·-第45章-长信一","aria-label":'Permalink to "第三卷 潮汐 · 第45章 长信一"'},"​")],-1),e("p",null,"高二秋末，南雾县的雾又厚了起来。 早自习前的教室潮潮的，黑板擦过一遍还留着白印，风从后门缝钻进来，吹得窗帘轻轻晃。 林小满从前门跑进来，手里举着牛皮纸信封，脸跑得通红。 她把信封拍在我桌上，声音压得很低。 “沈聿，你的信，好厚。” 我指尖碰到信封，粗糙纸面带着凉意。 封口贴着一颗小小纸星星，棱角分明。 字迹我认得，是江苒的。 她去雾山市里已有些日子，我们只靠托人带话联系。 我把信塞进抽屉，没敢当场拆。 陈默用笔帽敲敲我的桌角。 “脸红什么，心跳我都听见了。” 我没理他，看向窗外。 操场全是雾，远处的树只剩影子，空气里有落花淡香，还有食堂的热气。 好不容易熬到中午，我抱着信去了天台。 铁门有点锈，推开时轻响，风灌进衣领。 我找背风角落坐下，慢慢撕开信封。 里面是好几页信纸，写得满满的，边角画着小小浪花。 开头她写天气，说雾山市里风大，夜里能听见窗响。 接着写新同桌，说对方安静，下课喜欢看云。 我看得很慢，手指摩挲纸面，能感到她下笔轻重。 信纸带着墨水味，还有阳光晒过的暖。 读到后面，我的心忽然跳快了。 她说住处附近有个小店，店里有部公用电话。 号码写在那页背面，字很小，又描了一遍。 她说看到号码时手心一直在出汗。 她说，她好想我。 那几个字写得很重，纸都洇出毛边。 我耳朵一下热起来，风也压不住。 天台很静，只有水箱滴水声，一声，又一声。 我把那页翻过去又翻回来，号码看了一遍又一遍。 口袋里还有她留的海盐糖，我剥一颗放进嘴里。 甜里带一点咸，化开时舌尖发凉。 我忽然很慌，不知该把这页放哪里。 放进口袋怕皱，夹进书里怕被翻到，握在手里怕汗弄花字。 顾远上来找我，看我这样笑了。 “又收到信了？” 我点点头，把信合上。 他坐我旁边，递给我一颗小石子。 “想打就打，慌什么。” 我说，我慌。 他问，慌什么。 我说不清，就是心口发紧，像有什么要漫出来。 下午上课，我一直在走神。 叶老师在黑板写字，粉笔灰落下来，细细的。 何晓回头看我几次，用眼神问我怎么了，我只摇头。 熬到晚自习结束，宿舍很吵，有水声，有暖壶碰响，还有脚步声。 我躺床上，把信又看一遍。 最后一段，她写以后每周六傍晚，她会在小店门口等。 若我想她，可以打那个电话。 若那天没打，就是不打了，她不会多想，让我别有负担。 看到这里，我眼眶发酸。 林小满的话响在耳边，她说江苒一定写了很久。 陈默也说过，信越长越不敢回。 我把信贴在胸口，能听见心跳，盖过走廊喧闹。 被子有肥皂清香，混着秋天被褥软暖气息。 我翻身下床，从箱子里找出那盘旧磁带。 那是她录给我的，有她哼的歌，还有潮水声。 塑料壳贴着手心，冰凉，让人安定。 我拿出纸笔，想回信。 写了开头又划掉，划掉又重写。 想告诉她，南雾县雾很大，早上看不清路。 想告诉她，宋阿婆还问起她，说她叠的纸星星最好看。 想告诉她，我也很想她。 可笔尖落下，又觉这些话太轻，压不住分量。 夜深了，熄灯了，走廊光从门缝透进来，细细一条。 我把纸星星放枕边，棱角硌着手指，有点疼，却舍不得拿开。 我在心里把号码背一遍，每个音都烫嘴。 周六，多么远，又多么近。 我想象小店门口模样，想象电话响起声音，想象她接起说喂的样子。 光是想象，手心就出汗。 我把脸埋进被子，暖气裹着我，眼泪却悄悄下来。 原来想念是这味道，像含着海盐糖，甜里带咸，咽下喉咙发紧。 我明白她写下电话的心情。 那不只是一串号码，那是把心摊开，问一句，你会来吗。 而我慌，是太想去，又怕听见忙音，又怕语无伦次。 我在黑暗里对自己说，周六打。 没打，就是不打了。 这句话像潮水，一遍遍漫过心口。 第二天清晨，雾没散，我把信折好装回信封。 就在这时，发现信封内侧还有一行铅笔小字，淡得差点错过。 我手停在半空，心跳漏了一拍。",-1)])])}const h=t(n,[["render",_]]);export{f as __pageData,h as default};
